import{_ as o,o as a,c as t,a2 as i}from"./chunks/framework.Bg-Zxr5O.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Matrix-MGET-Command.md","filePath":"manual-en/Matrix-MGET-Command.md","lastUpdated":1785684581000}'),c={name:"manual-en/Matrix-MGET-Command.md"};function d(r,e,n,p,s,m){return a(),t("div",null,[...e[0]||(e[0]=[i('<h4 id="_16-4-11-the-mget-command" tabindex="-1">16.4.11 The <code>MGET</code> Command <a class="header-anchor" href="#_16-4-11-the-mget-command" aria-label="Permalink to &quot;16.4.11 The `MGET` Command&quot;">​</a></h4><pre><code>MGET [/FILE=_file_]\n     [/TYPE={COV _|_ CORR _|_ MEAN _|_ STDDEV _|_ N _|_ COUNT}].\n</code></pre><p>The <code>MGET</code> command reads the data from a matrix file (see <a href="./Matrix-Files">Matrix Files</a>) into matrix variables.</p><p>All of <code>MGET</code>’s subcommands are optional. Specify the name or handle of the matrix file to be read on the <code>FILE</code> subcommand; if it is omitted, then the command reads the active file.</p><p>By default, <code>MGET</code> reads all of the data from the matrix file. Specify a space-delimited list of matrix types on <code>TYPE</code> to limit the kinds of data to the one specified:</p><p><code>COV</code></p><p>Covariance matrix.</p><p><code>CORR</code></p><p>Correlation coefficient matrix.</p><p><code>MEAN</code></p><p>Vector of means.</p><p><code>STDDEV</code></p><p>Vector of standard deviations.</p><p><code>N</code></p><p>Vector of case counts.</p><p><code>COUNT</code></p><p>Vector of counts.</p><p><code>MGET</code> reads the entire matrix file and automatically names, creates, and populates matrix variables using its contents. It constructs the name of each variable by concatenating the following:</p><ul><li>A 2-character prefix that identifies the type of the matrix:</li></ul><p><code>CV</code></p><p>Covariance matrix.</p><p><code>CR</code></p><p>Correlation coefficient matrix.</p><p><code>MN</code></p><p>Vector of means.</p><p><code>SD</code></p><p>Vector of standard deviations.</p><p><code>NC</code></p><p>Vector of case counts.</p><p><code>CN</code></p><p>Vector of counts.</p><ul><li>If the matrix file has factor variables, <code>F _n_</code>, where <em>n</em> is a number identifying a group of factors: <code>F1</code> for the first group, <code>F2</code> for the second, and so on. This part is omitted for pooled data (where the factors all have the system-missing value).</li><li>If the matrix file has split file variables, <code>S _n_</code>, where <em>n</em> is a number identifying a split group: <code>S1</code> for the first group, <code>S2</code> for the second, and so on.</li></ul><p>If <code>MGET</code> chooses the name of an existing variable, it issues a warning and does not change the variable.</p>',33)])])}const h=o(c,[["render",d]]);export{f as __pageData,h as default};
